-- Leonard Larson (profileID=12) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Leonard Larson phrasings

SELECT p.argumentID, p.phrasingID, 12, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 12
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 12 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=12 AND targArgID IN (106,107,134,136,141,145,148,153,155,165,182,193,200,230,242,275,276,277,288,293,321,329,331,333,355,356,403,404,405,408,409,410,411,412,414,428,433,447,478,494,527,530,560,561,572,609,611,636,696,698,701,743,894,895,896,897,901,910);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 12
SET pe.active = o.acceptance
WHERE pe.profileID = 12;

SELECT 'Done: endorsements for profileID=12' AS status;